116		data := event.JSON()
117		if len(data) == 0 {
118			return
119		}
120		h.mu.RLock()
121		defer h.mu.RUnlock()
122		for c := range h.clients {
123			if !c.canReceive(event) {
124				continue
125			}
126			select {
